contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry containing the property test.
    // We take a description string as input and assert relation between c.isAdmin(this) and whether the call reverts.
    function run(string calldata description) public payable {
        // Observe whether this contract is an admin according to the public getter
        bool selfIsAdmin = c.isAdmin(address(this)); if (__ESBMC_reverted()) return;

        // Execute the state-changing call directly on c and capture revert using try/catch
        bool reverted;
        c.newEmergencyOracle(description); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // General rule: the call reverts exactly when this contract is not an admin as reported by c.isAdmin
        assert(reverted == (!selfIsAdmin));
    }

    receive() external payable {}
}

